const express = require("express");

const router = express.Router();

const {
    createReview,
    updateReview,
    deleteReview
} = require("../controllers/reviewController");

// POST recensione
router.post("/", createReview);

// PUT recensione
router.put("/:id", updateReview);

// DELETE recensione
router.delete("/:id", deleteReview);

module.exports = router;